-- Élargit la zone de couverture des POI (sommets/cols/points de vue/monuments/parcs) x2
-- en rayon (~x4 en surface) autour de Chambéry et Rouen — la zone initiale (013/014)
-- laissait de côté des lieux notables un peu plus loin du centre pilote.
-- `on conflict (id) do nothing` : les lieux déjà importés (zone d'origine) sont ignorés,
-- seuls les nouveaux (zone élargie) sont ajoutés.
